 3	export function createDraftEditor({ store, timers, renderDocument, renderStatus }) {
 4	  let current = null;
 5	  function close() {
 6	    const leaving = current;
 7	    current = null;
 8	    if (leaving) leaving.stop();
 9	    renderDocument(null);
10	  }
11	  return {
12	    open(id) {
13	      close();
14	      current = { id, text: store.read(id), visit: {}, stop: attachSaveStatus(store, id, renderStatus) };
15	      renderDocument({ id, text: current.text });
16	    },
17	    edit(text) {
18	      if (!current) return;
19	      current.text = text;
20	      store.write(current.id, text);
21	    },
22	    selection() {
23	      return current && { id: current.id, text: current.text, visit: current.visit };
24	    },
25	    close,
26	  };
27	}
