 3	// Coalesce calls until a quiet interval. cancel discards work; flush runs it now.
 4	// Retire the old batch before invoking work, which can enqueue another batch.
 5	export function createTrailingTask(work, delay, timers = browserTimers) {
 6	  let handle = null;
 7	  let pending = null;
 8	  function flush() {
 9	    if (handle !== null) timers.cancel(handle);
10	    handle = null;
11	    const args = pending;
12	    pending = null;
13	    if (args !== null) work(...args);
14	  }
15	  return {
16	    push(...args) {
17	      if (handle !== null) timers.cancel(handle);
18	      pending = args;
19	      handle = timers.schedule(flush, delay);
20	    },
21	    flush,
22	    cancel() {
23	      if (handle !== null) timers.cancel(handle);
24	      handle = null;
25	      pending = null;
26	    },
27	  };
28	}
 1	// A synchronous workspace store, independent of whether an editor is visible.
 2	// Notifications run inline after the record is written. Subscribers may detach
 3	// or subscribe while a notification is being delivered.
 4	export function createDraftStore(initial = {}) {
 5	  const records = new Map(Object.entries(initial));
 6	  const listeners = new Set();
 7	  let revision = 0;
 8	  return {
 9	    read(id) { return records.get(id) ?? ""; },
10	    write(id, text) {
11	      records.set(id, text);
12	      const event = { id, text, revision: ++revision };
13	      for (const listener of [...listeners]) {
14	        if (listeners.has(listener)) listener(event);
15	      }
16	      return event;
17	    },
18	    subscribe(listener) {
19	      listeners.add(listener);
20	      return () => listeners.delete(listener);
21	    },
22	  };
23	}
 1	import { createDraftEditor } from "./editor.js";
