 3	export function createWorkspace({ store, archive, timers, renderDocument, renderStatus,
 4	  renderSubmission = () => {}, onSaved = () => {} }) {
 5	  const stop = store.subscribe(event => onSaved(event, navigation));
 6	  const editor = createDraftEditor({ store, timers, renderDocument, renderStatus });
 7	  const navigation = {
 8	    open(id) { renderSubmission(null); editor.open(id); },
 9	    edit(text) { editor.edit(text); },
10	    close() { renderSubmission(null); editor.close(); },
11	    submit() {
12	      const origin = editor.selection();
13	      if (!origin) return null;
14	      const receipt = archive.capture({ id: origin.id, text: origin.text });
15	      renderSubmission(receipt);
16	      return receipt;
17	    },
18	  };
19	  return { ...navigation, dispose() { stop(); navigation.close(); } };
20	}
 1	// A mounted document's save badge. A close/open request retires the departing
 2	// badge immediately: it must produce no further output, including during that
 3	// navigation call. Saving the document itself is a separate workspace concern.
 4	export function attachSaveStatus(store, id, renderStatus) {
 5	  return store.subscribe(event => {
 6	    if (event.id === id) renderStatus(event);
 7	  });
 8	}
