 3	export function createSearchPreview({ timers, publish }) {
 4	  const task = createTrailingTask(query => publish({ query }), 40, timers);
 5	  return {
 6	    query(text) { task.push(text); },
 7	    // A hidden preview has no use for a pending query; reopen starts fresh.
 8	    hide() { task.cancel(); },
 9	  };
10	}
