 1	// A downstream consumer: archived submissions are value snapshots, not live
 2	// references to a draft. capture/list never invoke application integrations.
 3	export function createReceiptArchive() {
 4	  const receipts = [];
 5	  return {
 6	    capture({ id, text }) {
 7	      const receipt = Object.freeze({ id, text });
 8	      receipts.push(receipt);
 9	      return receipt;
10	    },
11	    list() { return receipts.map(receipt => ({ ...receipt })); },
12	  };
13	}
